{
 "problem": "list_users() returns every user, which times out for large tenants. An optional limit parameter is needed to bound result size while keeping existing zero-argument callers working.",
 "scope": [
  "Add an optional `limit` argument to list_users.",
  "Default limit is 100; maximum accepted value is 1000; values below 1 raise ValueError."
 ],
 "non_goals": [
  "Pagination or offset/cursor support.",
  "Changes to any function other than list_users.",
  "Any schema change or destructive database operation."
 ],
