  "The API owner's agreement in COMMENT-1 is the authoritative decision for default, maximum, and error behavior.",
  "Callers passing values above 1000 will be rejected or clamped; the choice is not stated in the sources."
 ],
 "current_behavior": [
  {
   "claim": "list_users(db) issues an unbounded SELECT * FROM users query and returns all rows.",
   "source_ids": ["SRC-1"]
  },
  {
   "claim": "Large tenants experience timeouts when listing users.",
   "source_ids": ["ISSUE"]
  }
 ],
 "proposed_change": "Add an optional limit parameter to list_users defaulting to 100, bounding returned rows to min(limit, available users); validate limit is an integer in [1, 1000] and raise ValueError otherwise.",
 "api_changes": "list_users gains an optional keyword argument `limit` (default 100). Zero-argument callers see at most 100 users. Values < 1 raise ValueError.",
 "alternatives": [
  "Pagination with offset/cursor, deferred as larger scope than the issue requests."
 ],
 "risks": [
  "Callers relying on receiving all users will silently receive truncated results.",
  "Behavior for limit > 1000 is unspecified and must be decided before implementation."
 ],
 "requirements": [
  {
   "id": "REQ-1",
   "description": "list_users(db) with no limit argument returns at most 100 users.",
   "source_ids": ["ISSUE"],
   "test_ids": ["TEST-1"]
  },
  {
   "id": "REQ-2",
   "description": "list_users(db, limit=n) for 1 <= n <= 1000 returns at most n users.",
   "source_ids": ["ISSUE", "COMMENT-1"],
   "test_ids": ["TEST-2"]
  },
  {
   "id": "REQ-3",
   "description": "list_users(db, limit=n) with n < 1 raises ValueError.",
   "source_ids": ["COMMENT-1"],
   "test_ids": ["TEST-3"]
  }
 ],
 "acceptance_tests": [
  {
   "id": "TEST-1",
   "expected_behavior": "With 250 seeded users, list_users(db) returns exactly 100 users."
  },
  {
   "id": "TEST-2",
   "expected_behavior": "With 250 seeded users, list_users(db, limit=7) returns exactly 7 users."
  },
  {
   "id": "TEST-3",
   "expected_behavior": "list_users(db, limit=0) and list_users(db, limit=-1) each raise ValueError."
  }
 ],
 "work_items": [
  {
   "id": "TASK-1",
   "objective": "Add limit parameter with default 100, validation, and LIMIT clause to the query.",
   "depends_on": []
  },
  {
   "id": "TASK-2",
   "objective": "Add tests TEST-1 through TEST-3 covering default, bounded, and invalid inputs.",
   "depends_on": ["TASK-1"]
  }
 ],
 "timeline": [
  {
   "id": "MILESTONE-1",
   "phase": "Implementation",
   "deliverable": "Updated list_users with limit parameter and validation.",
   "exit_criteria": "list_users accepts limit and TASK-1 code is merged.",
   "depends_on": []
  },
  {
   "id": "MILESTONE-2",
   "phase": "Verification",
   "deliverable": "Tests TEST-1 through TEST-3 passing.",
   "exit_criteria": "All three acceptance tests pass against the pinned commit.",
   "depends_on": ["MILESTONE-1"]
  }
 ],
 "constraints": [
  "Read-only specification; no database operations are part of this change.",
  "Preserve compatibility for zero-argument callers."
 ],
 "rollout_rollback": "Ship behind normal release process; rollback by reverting the limit parameter, restoring unbounded behavior.",
 "unresolved_questions": [
  "What should happen when limit > 1000: reject with ValueError or clamp to 1000?",
  "Is returning truncated results to existing zero-argument callers acceptable, given the behavior change?",
  "Should the 1000 maximum be enforced in the function or only documented?"
 ]
}
EOF
```

