```mswea_bash_command
validate_draft <<'EOF'
{
 "problem": "CSV export emits columns in an arbitrary order that changes between runs, breaking downstream imports that expect the order defined by FIELDS.",
 "scope": [
  "Column order of the header row and every data row produced by export() in export.py.",
  "Column order must match FIELDS exactly, with the header row included."
 ],
 "non_goals": [
  "Changing the contents or set of fields in FIELDS.",
  "Changing the row serialization format beyond column ordering.",
  "Auth behavior in auth.py (SRC-2 is out of scope for this issue)."
 ],
 "assumptions": [
  "FIELDS is the authoritative ordering as stated by the reporter and confirmed in COMMENT-1.",
  "Downstream consumers rely on positional column order and do not rely on the current random order."
 ],
 "current_behavior": [
  {
   "claim": "export() builds the column list from set(FIELDS), which has no defined iteration order, so column order varies between runs.",
   "source_ids": ["SRC-1"]
  },
  {
   "claim": "Reporters observe random column order in exported CSV files between runs.",
   "source_ids": ["ISSUE"]
  }
 ],
 "proposed_change": "Replace set(FIELDS) with an ordered iteration over FIELDS in export() so the header and each data row follow FIELDS order.",
 "api_changes": "None expected; export(rows) signature and return type are unchanged. Output column order becomes deterministic.",
 "alternatives": [
  "Sort columns alphabetically; rejected because COMMENT-1 requires FIELDS order exactly."
 ],
 "risks": [
  "Consumers that accidentally depended on the previous ordering may see changed output; the prior ordering was non-deterministic so this is unlikely to be relied upon."
 ],
 "requirements": [
  {
   "id": "REQ-1",
   "description": "The header row of exported CSV lists columns in exactly the order of FIELDS.",
   "source_ids": ["ISSUE", "COMMENT-1"],
   "test_ids": ["TEST-1"]
  },
  {
   "id": "REQ-2",
   "description": "Every data row lists values in exactly the order of FIELDS, consistent with the header.",
   "source_ids": ["ISSUE", "COMMENT-1"],
   "test_ids": ["TEST-2"]
  },
  {
   "id": "REQ-3",
   "description": "Column order is identical across repeated invocations of export() on the same input.",
   "source_ids": ["ISSUE"],
   "test_ids": ["TEST-3"]
  }
 ],
 "acceptance_tests": [
  {
   "id": "TEST-1",
   "expected_behavior": "For FIELDS = ['id','name','email'], the first line of export(rows) equals 'id,name,email'."
  },
  {
   "id": "TEST-2",
   "expected_behavior": "For each row r, the k-th comma-separated value of the data line equals str(r[FIELDS[k]])."
  },
  {
   "id": "TEST-3",
   "expected_behavior": "Calling export(rows) 50 times on the same input yields byte-identical output each time."
  }
 ],
 "work_items": [
  {
   "id": "TASK-1",
   "objective": "Change export() in export.py to iterate FIELDS in order for both header and data rows instead of set(FIELDS).",
   "depends_on": []
  },
  {
   "id": "TASK-2",
   "objective": "Add tests TEST-1, TEST-2, and TEST-3 covering header order, row alignment, and run-to-run stability.",
   "depends_on": ["TASK-1"]
  }
 ],
 "timeline": [
  {
   "id": "MILESTONE-1",
   "phase": "Fix ordering",
   "deliverable": "export.py uses FIELDS order for header and rows.",
   "exit_criteria": "TEST-1 and TEST-2 pass against the modified export().",
   "depends_on": []
  },
  {
   "id": "MILESTONE-2",
   "phase": "Stability verification",
   "deliverable": "Regression tests covering repeated-run determinism.",
   "exit_criteria": "TEST-3 passes consistently across repeated runs.",
   "depends_on": ["MILESTONE-1"]
  }
 ],
 "constraints": [
  "Read-only specification; no code changes are made by this document.",
  "Evidence limited to the pinned commit bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb."
 ],
 "rollout_rollback": "Deploy the ordering fix; rollback by reverting the export.py change. Rollback restores non-deterministic ordering, so it should only be used if a consumer breaks for an unrelated reason.",
 "unresolved_questions": [
  "Whether any existing downstream consumer depends on the previous ordering has not been verified from supplied sources.",
  "Whether FIELDS is ever mutated at runtime was not verified; only SRC-1 lines 1-5 were supplied.",
  "Handling of rows missing a key in FIELDS is not covered by supplied evidence."
 ]
}
EOF
```

